private boolean isEntryHost(String header) {
    if (header == null) return false;
    String value = header.strip();
    int colon = value.startsWith("[") ? value.indexOf("]:") : value.lastIndexOf(':');
    String host;
    String port;
    if (colon < 0) { host = value; port = ""; }
    else if (value.startsWith("[") && colon == value.indexOf("]:") ) { host = value.substring(0, colon+1); port = value.substring(colon+2); }
    ...
}
